    reac_lines = [l for l in Path(rng.reactionfilename).read_text().splitlines() if l.strip()]

def ts_bonds(bo):
    return frozenset((a-1, b-1, int(bo[tuple(sorted((a,b)))])) for a,b in EDGES)

smi2bonds = {}
