    smi, atoms, bonds = l.split(" ")
    smi2bonds[smi] = frozenset(tuple(map(int, e.split(","))) for e in bonds.split(";"))

n_distinct = len({frozenset((k, v) for k, v in p.items()) for p in patterns})
